/*
 PLAN
 1. Composition: backdrop gradient plane 7x6 @ z=-2.5; pricing card slab 2.4x3.2 centered (~60% frame height) at z=0; machined header strip on top edge; text stack (tier, price+caption, 4 feature rows with hairlines, CTA bar) at z=+0.02..0.06; contact shadow below.
 2. Light rig: rig-product-hero — warm key spot #fff2e0 int 65 upper-left-front, fill point #d8dde6 int 4 left, rim spot #ffffff int 48 behind-left; ambient floor 0.1; node-local, bounded.
 3. Materials: card slab MeshStandardNodeMaterial #16161d roughness 0.55 metalness 0.35; header strip brushed metal (TSL anisotropic band, roughness 0.55 metalness 0.5, clearcoat via physical); CTA engineered vertical gradient #ff4450->#c1121f with #ff2a38 perimeter emissive 1.5; backdrop TSL vertical grade.
 4. Motion: weighted-settle scale 1.04->1.0 over 0.9s power4.out with key specular band drag (light sweep), feature rows fade-up stagger 80ms, CTA press 0.97 in 120ms via userData.handlers.
 5. Focal element: the CTA row's red gradient/emissive is the single brightest read; everything else graded below it.
*/
import { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, SpotLight, PointLight, AmbientLight, Object3D, Color, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, mix, smoothstep, sin, float, uniform, positionLocal, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primHandles = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#16161d',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    grad0: (colors.gradientStops && colors.gradientStops[0]?.hex) ?? '#ff4450',
    grad1: (colors.gradientStops && colors.gradientStops[1]?.hex) ?? '#c1121f',
  };

  // ---------- backdropStage: graded stage, never void ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vUv = uv();
    const bottom = vec3(new Color(C.background).toArray());
    const top = mix(vec3(new Color(C.surface).toArray()), vec3(new Color(C.background).toArray()), float(0.35));
    // vertical grade with a soft radial lift behind the card
    const radial = smoothstep(float(0.85), float(0.15), length(vUv.sub(vec2(0.5, 0.52)).mul(vec2(1.35, 1.0))));
    const base = mix(bottom, top, vUv.y);
    backdropMat.colorNode = mix(base, vec3(new Color('#1c1c26').toArray()), radial.mul(0.55));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- lightRig: rig-product-hero (node-local, bounded) ----------
  const R = 1.7; // subject bounding radius
  const rig = new Group();
  const keyTarget = new Object3D(); keyTarget.position.set(0, 0.5 * R * 0.5, 0); rig.add(keyTarget);
  const key = new SpotLight(new Color('#fff2e0'), 65);
  key.position.set(2.2 * R, 3.2 * R, 2.4 * R);
  key.angle = 0.5; key.penumbra = 0.55; key.decay = 2; key.distance = 20;
  key.target = keyTarget; rig.add(key);

  const fill = new PointLight(new Color('#d8dde6'), 4, 9, 2);
  fill.position.set(-2.8 * R, 0.9 * R, 2 * R); rig.add(fill);

  const rimTarget = new Object3D(); rimTarget.position.set(0, 0.7 * R * 0.5, 0); rig.add(rimTarget);
  const rim = new SpotLight(new Color('#ffffff'), 48);
  rim.position.set(-1.6 * R, 2.6 * R, -2.2 * R);
  rim.angle = 0.6; rim.penumbra = 0.4; rim.decay = 2; rim.distance = 20;
  rim.target = rimTarget; rig.add(rim);

  const amb = new AmbientLight(new Color('#1a1c22'), 0.1); rig.add(amb);
  group.add(rig);

  // ---------- cardSlab ----------
  const card = new Group();
  group.add(card);
  const CARD_W = 2.4, CARD_H = 3.2, PAD = 0.5;

  const slabGeo = new BoxGeometry(CARD_W, CARD_H, 0.08);
  const slabMat = new MeshStandardNodeMaterial({ color: new Color(C.surface), roughness: 0.55, metalness: 0.35 });
  const slab = new Mesh(slabGeo, slabMat);
  card.add(slab);
  disposables.push(slabGeo, slabMat);

  // hairlineBorder: 0.006 hairline #2a2a33 perimeter
  const borderMat = new MeshBasicNodeMaterial({ color: new Color('#2a2a33') });
  const bT = 0.006;
  const borderGeos = [];
  const mkLine = (w, h, x, y) => {
    const g = new PlaneGeometry(w, h);
    const m = new Mesh(g, borderMat);
    m.position.set(x, y, 0.045);
    card.add(m); borderGeos.push(g);
  };
  mkLine(CARD_W, bT, 0, CARD_H / 2 - bT / 2);
  mkLine(CARD_W, bT, 0, -CARD_H / 2 + bT / 2);
  mkLine(bT, CARD_H, -CARD_W / 2 + bT / 2, 0);
  mkLine(bT, CARD_H, CARD_W / 2 - bT / 2, 0);
  disposables.push(borderMat, ...borderGeos);

  // ---------- headerStrip: brushed machined metal with sweepable specular band ----------
  const stripGeo = new BoxGeometry(CARD_W, 0.08, 0.09);
  const stripMat = new MeshPhysicalNodeMaterial({ color: new Color('#3a3a44'), roughness: 0.55, metalness: 0.5, clearcoat: 0.2, clearcoatRoughness: 0.35 });
  const sweep = uniform(-0.4); // animated specular band position (0..1 across strip)
  {
    const x = uv().x;
    // brushed anisotropy: fine horizontal micro-striations
    const striate = sin(x.mul(680.0)).mul(0.5).add(0.5).mul(0.06);
    const band = smoothstep(float(0.12), float(0.0), x.sub(sweep).abs()).mul(0.9);
    const base = vec3(new Color('#3a3a44').toArray());
    stripMat.colorNode = base.add(vec3(striate));
    stripMat.emissiveNode = vec3(new Color('#e8ecf2').toArray()).mul(band.mul(0.5));
    stripMat.roughnessNode = float(0.55).sub(striate.mul(0.6));
  }
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, CARD_H / 2 - 0.04, 0.005);
  card.add(strip);
  disposables.push(stripGeo, stripMat);

  // ---------- textStack via ctx.fontAtlas ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const leftX = -CARD_W / 2 + PAD;
  const Z = 0.06;

  const tierItem = byRole('tier-name')[0];
  const tierText = ctx.fontAtlas.createText(tierItem?.text ?? 'ATELIER RESERVE', { fontSize: 20, color: C.paper, align: 'left', letterSpacingPx: 1.6 });
  tierText.position.set(leftX, CARD_H / 2 - PAD - 0.1, Z);
  card.add(tierText);

  const priceItem = byRole('price')[0];
  const priceText = ctx.fontAtlas.createText(priceItem?.text ?? '$480', { fontSize: 62, color: C.paper, align: 'left' });
  priceText.position.set(leftX, CARD_H / 2 - PAD - 0.48, Z);
  card.add(priceText);

  const capItem = byRole('caption')[0];
  const capText = ctx.fontAtlas.createText(capItem?.text ?? 'PER MONTH, BILLED ANNUALLY', { fontSize: 9, color: '#9aa2ad', align: 'left', letterSpacingPx: 1.1 });
  capText.position.set(leftX, CARD_H / 2 - PAD - 0.72, Z);
  card.add(capText);

  // feature rows: 0.375h each, hairline separators #23232b
  const hairMat = new MeshBasicNodeMaterial({ color: new Color('#23232b') });
  const hairGeo = new PlaneGeometry(CARD_W - 2 * PAD, 0.006);
  disposables.push(hairMat, hairGeo);
  const featureItems = byRole('feature');
  const featureRows = [];
  const rowsTop = CARD_H / 2 - PAD - 1.02; // 0.5-unit gap after price block
  featureItems.forEach((item, i) => {
    const row = new Group();
    const t = ctx.fontAtlas.createText(item.text, { fontSize: 13, color: C.paper, align: 'left' });
    t.position.set(leftX, 0, 0);
    row.add(t);
    const hl = new Mesh(hairGeo, hairMat);
    hl.position.set(0, -0.1875, -0.005);
    row.add(hl);
    row.position.set(0, rowsTop - i * 0.375, Z);
    card.add(row);
    featureRows.push(row);
  });

  // ---------- ctaRow: focal — engineered gradient + perimeter emissive ----------
  const cta = new Group();
  const ctaGeo = new BoxGeometry(1.4, 0.36, 0.06);
  const ctaMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.2 });
  {
    const y = uv().y;
    const grad = mix(vec3(new Color(C.grad1).toArray()), vec3(new Color(C.grad0).toArray()), y); // bottom c1121f -> top ff4450
    ctaMat.colorNode = grad;
    // perimeter emissive #ff2a38 intensity 1.5
    const px = uv().x, py = uv().y;
    const edge = smoothstep(float(0.05), float(0.0), px.min(float(1.0).sub(px)).min(py.min(float(1.0).sub(py))));
    ctaMat.emissiveNode = vec3(new Color(C.accent).toArray()).mul(edge.mul(1.5).add(grad.mul(0.0).x));
  }
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  cta.add(ctaMesh);
  const ctaLabelItem = byRole('cta-label')[0];
  const ctaText = ctx.fontAtlas.createText(ctaLabelItem?.text ?? 'JOIN THE RESERVE', { fontSize: 13, color: C.ink, align: 'center', letterSpacingPx: 1.1 });
  ctaText.position.set(0, 0, 0.04);
  cta.add(ctaText);
  cta.position.set(0, -CARD_H / 2 + PAD + 0.18, Z);
  card.add(cta);
  disposables.push(ctaGeo, ctaMat);

  // ---------- contactShadow ----------
  const shadowGeo = new CircleGeometry(1.6, 48);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  {
    const d = length(uv().sub(vec2(0.5)));
    shadowMat.colorNode = vec3(0, 0, 0);
    shadowMat.opacityNode = smoothstep(float(0.5), float(0.05), d).mul(0.5);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -CARD_H / 2 - 0.12, 0.2);
  shadow.scale.set(1, 0.45, 1);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- motion: weighted settle + specular sweep + feature stagger ----------
  const settle = gsap.timeline();
  card.scale.set(1.04, 1.04, 1.04);
  settle.to(card.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  settle.fromTo(sweep, { value: -0.25 }, { value: 1.25, duration: 0.9, ease: 'power2.out' }, 0);
  timelines.push(settle);

  const stagger = gsap.timeline();
  featureRows.forEach((row, i) => {
    row.position.y += 0.2;
    row.visible = true;
    const targetY = row.position.y - 0.2;
    stagger.to(row.position, { y: targetY, duration: 0.5, ease: 'power2.out' }, 0.25 + i * 0.08);
    row.scale.set(1, 0.001, 1);
    stagger.to(row.scale, { y: 1, duration: 0.5, ease: 'power2.out' }, 0.25 + i * 0.08);
  });
  timelines.push(stagger);

  // idle: single slow breathing <=2%
  const idle = gsap.to(card.scale, { x: 1.012, y: 1.012, z: 1.012, duration: 3.4, yoyo: true, repeat: -1, ease: 'sine.inOut', delay: 1.2 });
  timelines.push(idle);

  // ---------- primitives from config ----------
  for (const prim of config.cinematicPrimitives ?? []) {
    const h = ctx.primitives[prim.name](card, prim.params);
    if (h) primHandles.push(h);
  }

  // ---------- handlers ----------
  group.userData.handlers = {
    click: () => {
      const press = gsap.timeline();
      press.to(cta.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      press.to(cta.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power4.out' });
      timelines.push(press);
      ctx.emit('checkout.begin', { itemId: 'atelier-reserve' });
    },
    hover: () => {
      const tl = gsap.to(card.rotation, { y: 0.06, x: -0.03, duration: 0.3, ease: 'power2.out' });
      timelines.push(tl);
    },
    hoverend: () => {
      const tl = gsap.to(card.rotation, { y: 0, x: 0, duration: 0.3, ease: 'power2.out' });
      timelines.push(tl);
    },
  };

  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primHandles) h.cleanup && h.cleanup();
    for (const d of disposables) d.dispose && d.dispose();
    [tierText, priceText, capText, ctaText].forEach((t) => {
      t.geometry && t.geometry.dispose && t.geometry.dispose();
      t.material && t.material.dispose && t.material.dispose();
    });
    featureRows.forEach((row) => row.traverse((o) => {
      o.geometry && o.geometry !== hairGeo && o.geometry.dispose && o.geometry.dispose();
      o.material && o.material !== hairMat && o.material.dispose && o.material.dispose();
    }));
  };

  return group;
}

/* @spec-manifest
{"elements":[
{"id":"text.tier-name.0","where":"textStack","how":"tierText via fontAtlas, 20px, top-left"},
{"id":"text.price.1","where":"textStack","how":"priceText via fontAtlas, 62px Lora scale"},
{"id":"text.caption.2","where":"textStack","how":"capText 9px caption under price"},
{"id":"text.feature.3","where":"textStack","how":"featureRows[0] fontAtlas 13px row"},
{"id":"text.feature.4","where":"textStack","how":"featureRows[1] fontAtlas 13px row"},
{"id":"text.feature.5","where":"textStack","how":"featureRows[2] fontAtlas 13px row"},
{"id":"text.feature.6","where":"textStack","how":"featureRows[3] fontAtlas 13px row"},
{"id":"text.cta-label.7","where":"ctaRow","how":"ctaText ink label centered on CTA"},
{"id":"color.background","where":"backdropStage","how":"gradient base color #0b0b10"},
{"id":"color.surface","where":"cardSlab","how":"slabMat albedo #16161d"},
{"id":"color.ink","where":"ctaRow","how":"ctaText color #16161d on red"},
{"id":"color.paper","where":"textStack","how":"tier/price/feature text color #e8ecf2"},
{"id":"color.accent","where":"ctaRow","how":"perimeter emissiveNode #ff2a38 intensity 1.5"},
{"id":"color.gradient","where":"ctaRow","how":"TSL vertical mix ff4450 to c1121f"},
{"id":"effects.spec","where":"cardSlab","how":"2.4x3.2 slab, hairline border, headerStrip sweep, settle+stagger motion"}
]}
*/
